(() => {
 'use strict';
 const catalog=window.STUDY_CATALOGUE,T=window.StudyTools;if(!catalog||!T)return;
 const $=id=>document.getElementById(id),E=T.esc,root=new URL('./',location.href),link=q=>new URL(q.href,root).href;
 let semester='all',savedFilter='bookmark',focusTimer=null,remaining=15*60;
 const symbols={py1:'Py',py3:'Py',maths:'∫',fsd:'⌘',se:'◇',ps:'∑'};
 function subjectUrl(s,unit){if(s.id==='py1'||s.id==='py3')return `python/?book=${s.id==='py1'?'sem1':'sem3'}${unit?'&unit='+unit:''}`;if(s.id==='maths')return `maths/#q${unit===7?869:unit===8?967:643}`;if(s.id==='ps')return 'probability/'+(unit===4?'chapter-4.html':'');return `study/?subject=${s.id}${unit?'&unit='+unit:''}`;}
 function renderSubjects(){const items=T.state().items;$('study-subjects').innerHTML=catalog.subjects.filter(s=>semester==='all'||s.semester===Number(semester)).map(s=>{const done=catalog.questions.filter(q=>q.subject===s.id&&items[q.key]?.status==='done').length;return `<article class="subject-card" data-subject="${s.id}"><div class="subject-top"><span class="subject-symbol" aria-hidden="true">${symbols[s.id]}</span><span class="subject-sem">SEMESTER ${s.semester}</span></div><h3>${E(s.title)}</h3><span class="coverage-pill">${E(s.coverage)}</span><p>${E(s.note)}</p><div class="subject-progress">${done} / ${s.total} marked done</div><progress value="${done}" max="${s.total}" aria-label="${E(s.title)} study progress"></progress><details><summary>Browse ${s.chapters.length} chapters</summary><div class="chapter-links">${s.chapters.map(c=>`<a href="${subjectUrl(s,c.unit)}"><span>${c.unit} · ${E(c.title.replace(/^UNIT\s*\d+\s*[–—-]\s*/i,''))}</span><span>${c.total} Q</span></a>`).join('')}</div></details><a class="subject-open" href="${subjectUrl(s)}">Start practising →</a></article>`;}).join('');}
 function results(list,empty){return list.length?list.map(q=>`<a class="study-result" href="${E(q.href)}"><span><small>${E(catalog.subjects.find(s=>s.id===q.subject).title)} · Chapter ${q.unit} · Q${q.number}</small><strong>${E(q.question.slice(0,180))}${q.question.length>180?'…':''}</strong></span><span aria-hidden="true">↗</span></a>`).join(''):`<p class="study-small">${empty}</p>`;}
 function search(){const text=$('global-search').value.trim().toLowerCase(),subject=$('search-subject').value,number=/^(?:q\s*)?(\d+)$/.exec(text);const all=catalog.questions.filter(q=>(subject==='all'||q.subject===subject)&&(!text||(number?q.number===Number(number[1]):`${q.question} ${q.topic} ${q.unit}`.toLowerCase().includes(text))));$('search-count').textContent=text||subject!=='all'?`${all.length} matches${all.length>40?' · first 40 shown':''}`:'Search all '+catalog.questions.length+' available questions';$('global-results').innerHTML=text||subject!=='all'?results(all.slice(0,40),'No matching questions. Try a shorter topic or another subject.') : '';}
 function progress(){const list=catalog.questions,items=T.state().items;$('stat-done').textContent=list.filter(q=>items[q.key]?.status==='done').length;$('stat-revise').textContent=list.filter(q=>['revise','doubt'].includes(items[q.key]?.status)).length;$('stat-saved').textContent=list.filter(q=>items[q.key]?.bookmark).length;renderSubjects();renderSaved();}
 function renderSaved(){const items=T.state().items,list=catalog.questions.filter(q=>savedFilter==='bookmark'?items[q.key]?.bookmark:items[q.key]?.status===savedFilter);$('saved-results').innerHTML=results(list.slice(0,30),'Save a question or mark it for revision while studying. It will appear here.');document.querySelectorAll('[data-saved-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.savedFilter===savedFilter));}
 function practiceChapters(){const s=catalog.subjects.find(s=>s.id===$('practice-subject').value);$('practice-chapter').innerHTML='<option value="all">All available chapters</option>'+s.chapters.map(c=>`<option value="${c.unit}">${c.unit} · ${E(c.title)}</option>`).join('');}
 function practice(){const subject=$('practice-subject').value,chapter=$('practice-chapter').value;const pool=catalog.questions.filter(q=>q.subject===subject&&(chapter==='all'||q.unit===Number(chapter)));for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}const qs=pool.slice(0,Number($('practice-count').value));if(!qs.length){T.notice('No questions in this chapter.');return;}const d=T.modal('Your practice session',`<p class="study-small">Try ${qs.length} questions. Answers appear when you submit. Written questions are self-checked.</p><form id="practice-form">${qs.map((q,j)=>`<section class="practice-question"><strong>${j+1}. Q${q.number} · Chapter ${q.unit}</strong><p>${E(q.question)}</p>${q.options?.length&&q.answerIndex!==null?q.options.map((o,i)=>`<label><input type="radio" name="p${j}" value="${i}"><span>${E(o)}</span></label>`).join(''):`<label>Your working / answer<textarea name="p${j}" rows="3" placeholder="Write your answer before checking."></textarea></label>`}<div id="practice-review-${j}" hidden></div></section>`).join('')}<button type="submit" class="study-primary">Submit & check answers</button><div id="practice-summary" role="status"></div></form>`);
 let submitted=false;d.querySelector('form').onsubmit=e=>{e.preventDefault();if(submitted)return;submitted=true;let correct=0,mcq=0,attempted=0;qs.forEach((q,j)=>{const field=e.target.elements['p'+j],value=field?.value||'',objective=q.options?.length&&q.answerIndex!==null;if(value)attempted++;if(objective){mcq++;if(value!==''&&Number(value)===q.answerIndex)correct++;}const review=d.querySelector('#practice-review-'+j);review.hidden=false;review.className='practice-answer';review.innerHTML=`<strong>${objective?(value!==''&&Number(value)===q.answerIndex?'✓ Correct':'Check this answer'):'Compare your working'}</strong><p>${E(q.answer||'Open the full solution to compare your code and steps.')}</p>${q.explanation?`<p>${E(q.explanation)}</p>`:''}<a class="practice-review-link" href="${E(link(q))}">Open full solution ↗</a>`;});const summary=d.querySelector('#practice-summary');summary.className='practice-score';summary.textContent=`${attempted}/${qs.length} attempted. ${mcq?`${correct}/${mcq} MCQs correct.`:''} ${qs.length-mcq?`${qs.length-mcq} written questions to self-check.`:''}`;e.target.querySelector('[type=submit]').disabled=true;T.saveSession({subject,chapter,total:qs.length,attempted,mcq,correct,at:Date.now()});summary.scrollIntoView?.({block:'nearest'});};}
 function boot(){if(!$('study-subjects'))return;$('search-subject').innerHTML='<option value="all">All subjects</option>'+catalog.subjects.map(s=>`<option value="${s.id}">${E(s.title)}</option>`).join('');$('practice-subject').innerHTML=catalog.subjects.map(s=>`<option value="${s.id}">${E(s.title)}</option>`).join('');document.querySelectorAll('[data-semester]').forEach(b=>b.onclick=()=>{semester=b.dataset.semester;document.querySelectorAll('[data-semester]').forEach(v=>v.setAttribute('aria-pressed',v===b));renderSubjects();});document.querySelectorAll('[data-saved-filter]').forEach(b=>b.onclick=()=>{savedFilter=b.dataset.savedFilter;renderSaved();});$('global-search').oninput=search;$('search-subject').onchange=search;$('practice-subject').onchange=practiceChapters;$('practice-start').onclick=practice;$('hero-start').onclick=()=>{$('study-subjects').scrollIntoView?.({behavior:'smooth',block:'start'});};$('focus-start').onclick=()=>{if(focusTimer){clearInterval(focusTimer);focusTimer=null;$('focus-start').textContent='Resume';return;}$('focus-start').textContent='Pause';focusTimer=setInterval(()=>{remaining--;$('focus-time').textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`;if(remaining<=0){clearInterval(focusTimer);focusTimer=null;remaining=900;$('focus-time').textContent='15:00';$('focus-start').textContent='Start';T.notice('Session complete. Take a short break.');}},1000);};window.addEventListener('study-change',progress);progress();search();practiceChapters();}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
